// Build the public API and CLI described in the supplied work order.
import {readFileSync} from 'node:fs';
import {fileURLToPath} from 'node:url';
import {resolve} from 'node:path';

const hasOwn=Object.prototype.hasOwnProperty;

const isNonNegSafeInt=v=>typeof v==='number'&&Number.isSafeInteger(v)&&v>=0;

const fail=message=>{throw new Error(message);};

function frameOf(section){
  return '### '+JSON.stringify(section.id)+'\n'+section.text+'\n';
}

function validate(sections,maxBytes){
  if(!isNonNegSafeInt(maxBytes))fail('maxBytes must be a nonnegative safe integer');
  if(!Array.isArray(sections))fail('sections must be an array');
  const ids=new Set();
  for(let i=0;i<sections.length;i+=1){
    if(!hasOwn.call(sections,i))fail(`sections[${i}] is a missing array slot`);
    const s=sections[i];
    if(typeof s!=='object'||s===null||Array.isArray(s))fail(`sections[${i}] must be a non-null object`);
    if(typeof s.id!=='string'||s.id==='')fail(`sections[${i}].id must be a nonempty string`);
    if(typeof s.text!=='string')fail(`sections[${i}].text must be a string`);
    if(!isNonNegSafeInt(s.priority))fail(`sections[${i}].priority must be a nonnegative safe integer`);
    if(typeof s.required!=='boolean')fail(`sections[${i}].required must be a boolean`);
    if(ids.has(s.id))fail(`duplicate section id ${JSON.stringify(s.id)}`);
    ids.add(s.id);
  }
}

export function packContext(sections,maxBytes){
  validate(sections,maxBytes);
  const entries=sections.map((s,index)=>{
    const frame=frameOf(s);
    return {id:s.id,index,priority:s.priority,required:s.required,frame,
      cost:Buffer.byteLength(frame,'utf8')};
  });

  const chosen=[];
  let used=0;

  for(const e of entries){
    if(!e.required)continue;
    chosen.push(e);
    used+=e.cost;
  }
  if(used>maxBytes)fail('required sections exceed maxBytes');

  const optional=entries.filter(e=>!e.required)
    .sort((a,b)=>b.priority-a.priority||a.index-b.index);
  const omittedIdx=new Set();
  for(const e of optional){
    if(used+e.cost<=maxBytes){
      chosen.push(e);
      used+=e.cost;
    }else{
      omittedIdx.add(e.index);
    }
  }

  const text=chosen.map(e=>e.frame).join('');
  return {
    text,
    bytes:Buffer.byteLength(text,'utf8'),
    included:chosen.map(e=>e.id),
    omitted:entries.filter(e=>omittedIdx.has(e.index)).map(e=>e.id)
  };
}

function main(argv){
  if(argv.length!==1)fail('usage: node context-packet.js INPUT_JSON_FILE');
  const raw=readFileSync(argv[0],'utf8');
  let parsed;
  try{
    parsed=JSON.parse(raw);
  }catch(err){
    fail(`invalid JSON input: ${err.message}`);
  }
  if(typeof parsed!=='object'||parsed===null||Array.isArray(parsed))fail('input must be a JSON object');
  const result=packContext(parsed.sections,parsed.maxBytes);
  process.stdout.write(JSON.stringify(result)+'\n');
}

const invoked=process.argv[1]&&resolve(process.argv[1])===resolve(fileURLToPath(import.meta.url));
if(invoked){
  try{
    main(process.argv.slice(2));
  }catch(err){
    process.stderr.write(`${err&&err.message?err.message:'error'}\n`);
    process.exitCode=2;
  }
}

import test from 'node:test';
import assert from 'node:assert/strict';
import {execFileSync, execFileSync as run} from 'node:child_process';
import {spawnSync} from 'node:child_process';
import {mkdtempSync, rmSync, writeFileSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {join, dirname} from 'node:path';
import {fileURLToPath} from 'node:url';
import {packContext} from '../context-packet.js';

const CLI=join(dirname(fileURLToPath(import.meta.url)),'..','context-packet.js');
const section=(id,text,priority=0,required=false)=>({id,text,priority,required});
const frame=s=>'### '+JSON.stringify(s.id)+'\n'+s.text+'\n';

test('rejects non-integer, negative and non-number budgets', () => {
  for(const bad of [-1,1.5,NaN,Infinity,'10',null,undefined,2**53]){
    assert.throws(()=>packContext([],bad),Error);
  }
});

test('rejects malformed sections without coercion', () => {
  const bads=[
    null,undefined,'x',42,[],
    {id:'',text:'t',priority:0,required:false},
    {id:1,text:'t',priority:0,required:false},
    {id:'a',text:1,priority:0,required:false},
    {id:'a',text:'t',priority:-1,required:false},
    {id:'a',text:'t',priority:'0',required:false},
    {id:'a',text:'t',priority:0.5,required:false},
    {id:'a',text:'t',priority:0,required:'true'},
    {id:'a',text:'t',priority:0},
    {id:'a',priority:0,required:false}
  ];
  for(const bad of bads)assert.throws(()=>packContext([bad],1000),Error,JSON.stringify(bad));
  assert.throws(()=>packContext('nope',10),Error);
});

test('exotic ids are valid and case sensitive', () => {
  const secs=[section('__proto__','a'),section('with space\nnl','b'),
    section('nul�','c'),section('A','d'),section('a','e')];
  const out=packContext(secs,10000);
  assert.deepEqual(out.included,['__proto__','with space\nnl','nul�','A','a']);
  assert.equal(out.text,secs.map(frame).join(''));
  assert.equal(out.omitted.length,0);
});

test('unknown fields ignored; inputs not mutated', () => {
  const input=[{id:'a',text:'t',priority:3,required:false,extra:{deep:1}}];
  const snapshot=JSON.stringify(input);
  assert.equal(packContext(input,1000).included.length,1);
  assert.equal(JSON.stringify(input),snapshot);
});

test('required order ignores priority; optional descending with input-order ties', () => {
  const secs=[section('r1','a',0,true),section('o1','b',5),section('o2','c',9),
    section('r2','d',99,true),section('o3','e',5)];
  const out=packContext(secs,10000);
  assert.deepEqual(out.included,['r1','r2','o2','o1','o3']);
  assert.equal(out.text,['r1','r2','o2','o1','o3']
    .map(id=>frame(secs.find(s=>s.id===id))).join(''));
});

test('skips oversized frames and reports omitted in input order', () => {
  const secs=[section('big','x'.repeat(50),9),section('mid','y'.repeat(40),8),
    section('small','z',7)];
  const budget=Buffer.byteLength(frame(secs[0]))+Buffer.byteLength(frame(secs[2]));
  const out=packContext(secs,budget);
  assert.deepEqual(out.included,['big','small']);
  assert.deepEqual(out.omitted,['mid']);
  assert.equal(out.bytes,budget);
});

test('multibyte cost is bytes not characters', () => {
  const s=section('id','\u{1F600}é');
  const bytes=Buffer.byteLength(frame(s));
  assert.equal(packContext([s],bytes).bytes,bytes);
  assert.deepEqual(packContext([s],bytes-1),{text:'',bytes:0,included:[],omitted:['id']});
});

test('required overflow throws rather than partial', () => {
  const secs=[section('r1','x',0,true),section('r2','y',0,true)];
  const one=Buffer.byteLength(frame(secs[0]));
  assert.throws(()=>packContext(secs,one),Error);
  assert.equal(packContext(secs,one*2).included.length,2);
});

test('empty text sections and zero budget', () => {
  assert.deepEqual(packContext([],0),{text:'',bytes:0,included:[],omitted:[]});
  assert.deepEqual(packContext([section('a','')],0),
    {text:'',bytes:0,included:[],omitted:['a']});
});

test('CLI behaviour', () => {
  const dir=mkdtempSync(join(tmpdir(),'ctxpkt-'));
  try{
    const good=join(dir,'good.json');
    writeFileSync(good,JSON.stringify({sections:[section('a','hi',1)],maxBytes:100,ignored:1}),'utf8');
    const ok=spawnSync(process.execPath,[CLI,good],{encoding:'utf8'});
    assert.equal(ok.status,0);
    assert.equal(ok.stderr,'');
    assert.equal(ok.stdout,JSON.stringify(packContext([section('a','hi',1)],100))+'\n');

    const badJson=join(dir,'bad.json');
    writeFileSync(badJson,'{nope','utf8');
    const cases=[[],[CLI,good,good],[CLI,join(dir,'missing.json')],[CLI,badJson]]
      .map(a=>a.length?a:[CLI]);
    for(const args of [[CLI],[CLI,good,good],[CLI,join(dir,'missing.json')],[CLI,badJson]]){
      const r=spawnSync(process.execPath,args,{encoding:'utf8'});
      assert.equal(r.status,2,args.join(' '));
      assert.equal(r.stdout,'');
      assert.ok(r.stderr.length>0);
    }

    const overflow=join(dir,'overflow.json');
    writeFileSync(overflow,JSON.stringify({sections:[section('r','x',0,true)],maxBytes:0}),'utf8');
    const r=spawnSync(process.execPath,[CLI,overflow],{encoding:'utf8'});
    assert.equal(r.status,2);
    assert.equal(r.stdout,'');
    assert.ok(r.stderr.length>0);
  }finally{
    rmSync(dir,{recursive:true,force:true});
  }
});

test('importing the module does not run the CLI', () => {
  const r=spawnSync(process.execPath,['--input-type=module','-e',
    `import(${JSON.stringify(CLI)}).then(m=>process.stdout.write(typeof m.packContext))`],
    {encoding:'utf8'});
  assert.equal(r.status,0);
  assert.equal(r.stdout,'function');
  assert.equal(r.stderr,'');
});

